export const TOKEN_SOURCE_TEXT = "/* SPDX-License-Identifier: Apache-2.0\n *\n * The one physical stylesheet of record for this app tree -- from zero, owned\n * in-repo, not a pointer into TraceFold_App/ui_proto (req/03 SS635, glovrex/\n * req/38 -- pointing a live dependency at a retired reference tree violates\n * the SS24 retirement methodology: the whole point of retiring that tree is\n * that nothing in this project may still need it to run). Every colour and\n * every size below was derived from the written design canon\n * (glovrex/req/38 SS551 Docker-IA chrome, SS553 36px tap targets + glyph-\n * first controls, SS558 14px body floor + light-default), computed fresh\n * against the WCAG 2.x relative-luminance formula (the same formula\n * parts/src/tokens.mjs's contrastRatio() re-implements to check this file at\n * test time) -- not read or copied from the retired file's own hex values.\n * parts/src/tokens.mjs still holds every name a part is allowed to spell\n * (CONSUMED); this file is the only place any of those names is given a\n * value.\n *\n * Location: this directory sits outside parts/, shell/kernel/, shell/demo/\n * and every per-face tree under faces/ on purpose. Each of those already\n * carries its own \"no colour literal / no second token roster\" gate that\n * walks its own directory (parts/test/tokens.test.mjs's declaring-file walk;\n * shell/tools/gates.mjs's \"the frame writes no colour\" gate over\n * shippedFiles(); each face's own tools/gate.mjs's shippedSources() over\n * FACE_ROOT) -- a stylesheet\n * that declares --bg/--ink/etc. would trip every one of those gates were it\n * placed inside the tree any of them walks. A dedicated top-level directory\n * is the one place in this app a real colour declaration can live without\n * being mistaken, by a gate built to look for exactly that, for a second\n * roster smuggled into a package that is supposed to hold none.\n */\n\n:root {\n  /* dark palette (bare :root -- parts/src/tokens.mjs's palettes() reads an\n     un-qualified :root block as the dark bucket; this is a parser contract\n     this file honours, not a claim that dark is the shipped default -- see\n     the light-default note below). */\n  /* Owner #388 (「theme無し・味気ない」, req/822_c7 §3): the dark page is no longer a\n     neutral near-black. #0a0a0c was exactly the generic-dark-devtool ground the design\n     memory forbids (feedback_design_not_generic_dark_devtool); every reference the Owner\n     handed over that reads as having an identity carries a hue in its ground (deep\n     ink-blue in four of the five dark references, req/822_c7 §1 E11). The identity this\n     app claims is its own: a witness ledger -- warm paper by day (the light bucket\n     below), night-audit ink by night. So the ground takes a blue-black ink cast, and\n     two elevation steps join it: --bg-raised (a panel one step off the page) and\n     --bg-inset (a well sunk into it). Every stated ratio below was re-measured against\n     the new ground with the same formula as before. */\n  --bg: #0d1016;\n  --bg-raised: #141926;  /* --ink on it: 14.32:1, --ink-2 on it: 6.63:1 */\n  --bg-inset: #090b10;\n  --ink: #e8e8e8;    /* measured 15.54:1 against --bg -- the subject: basename, a settled value */\n  --ink-2: #9f9f9f;  /* measured 7.19:1 -- the attendant: time, parent dir, disclosure body */\n  --ink-3: #838383;  /* measured 5.02:1 -- the aside: counts, an undone row. Forbidden for text\n                         use (parts/src/tokens.mjs FORBIDDEN_TOKENS) -- see the light side's\n                         measurement below for why. */\n  --line: #232a38;   /* one rule only, and it is the crease between sections -- carries the\n                         same ink cast as the ground it creases */\n  --deny: #e04a36;   /* measured 4.72:1 -- see the standing-hue block below for what this\n                         ink now sits inside (Owner #340 superseded the one-hue rule; the\n                         part of it that survives is that a verdict is never told apart by\n                         colour ALONE -- every mark still draws its own shape and prints\n                         its own word). */\n\n  /* Owner #340: 「単調でつまらない」. The rule this replaces was one hue for the whole\n     application (Deny) and grey for everything else, which is why a stranger at arm's\n     length could not tell an admitted row from a denied one from a held one: the three\n     differ by a 14px glyph and nothing else. What replaces it is not decoration. Each\n     standing this application can be in gets exactly one ink and one bed to sit that\n     ink on, so a filled chip is legible as a class before any word inside it is read,\n     and one further ink -- --act -- marks the things a hand may press, which nothing on\n     these screens marked at all.\n\n     Every figure below is measured with the same WCAG relative-luminance formula\n     parts/src/tokens.mjs re-implements, and every bed states the ratio of ITS OWN ink\n     against ITSELF, which is the number that matters for a filled chip (an ink measured\n     against the page is not the ink you are reading when it sits on a bed).\n     parts/test/tokens.test.mjs re-computes all of them at test time. */\n  --act: #63b8e8;         /* 8.66:1 against --bg -- pressable */\n  --act-bed: #0d1f28;     /* --act on it: 7.68:1 */\n  --admit: #52d18a;       /* 9.83:1 */\n  --admit-bed: #0e2417;   /* --admit on it: 8.45:1 */\n  --deny-bed: #1e0b08;    /* --deny on it: 4.70:1 */\n  --escalate: #e8a83c;    /* 9.16:1 */\n  --escalate-bed: #2a1e08; /* --escalate on it: 7.84:1 */\n  --held: #8ea6ff;        /* 8.21:1 */\n  --held-bed: #14192f;    /* --held on it: 7.48:1 */\n\n  /* SS553: 36px is the minimum tap target this app draws; a row is also\n     something a hand can land on (the note under it opens on click), so the\n     row pitch is unified with that same floor rather than carrying its own\n     smaller number. */\n  --row: 36px;\n\n  /* Declared for parity with the retired file's shape (a note-beside-row\n     layout axis) but consumed by nothing: parts/src/tokens.mjs's own\n     DETAIL_X_CONTRACT states plainly that no part in this tree positions a\n     note beside its row at any width -- every note stacks under its row\n     instead. The value is cosmetic until a part reads it; the collapse rule\n     below exists so the axis is honest about going to zero under 1000px\n     regardless. */\n  --detail-x: 700px;\n  --pad-x: 20px;\n  --spine-x: 64px;\n\n  /* Owner #349: corners. The application drew every edge square, or drew a radius\n     picked at the call site -- 2px on a rail item, 3px on a chip, 4px on a band, 8px\n     on a count pill -- which is four decisions nobody made once. Square reads harsh at\n     this density, and the reference idiom this project measures itself against\n     (req/784 I-2, I-5, I-10) rounds its cards at 6-8px.\n     Three tiers, and the tier is chosen by what the thing IS, not by taste: a mark-sized\n     thing that sits inside a line, a control a hand lands on, and a container that holds\n     other things. A fourth tier would be a tier nobody could name. */\n  --radius-1: 4px;   /* chips, count pills, badges -- inside a line of text */\n  --radius-2: 6px;   /* controls -- buttons, control rows, selects */\n  --radius-3: 8px;   /* containers -- boxes, bands, panes, cards */\n\n  /* Owner #348: motion, declared once so that every element moves the same way.\n     Two durations and one easing, because a system with five durations is a system\n     where nobody can say what the durations mean. `--motion-quick` is for a state a\n     finger is holding right now (press, hover) and must not lag behind the hand;\n     `--motion-settle` is for something arriving or leaving (a panel, a pane).\n     The curve decelerates: things arrive at rest rather than stopping dead, and nothing\n     in this application overshoots, because an overshoot on a ledger row is a row that\n     appears to move after it has settled. Both sit inside the 120-200ms band a reader\n     perceives as immediate-but-not-instant. */\n  --motion-quick: 120ms;\n  --motion-settle: 180ms;\n  --motion-ease: cubic-bezier(0.22, 0.61, 0.36, 1);\n\n  /* Two families, chosen by what the text IS, not by taste: mono for\n     anything typed or hashed (a path, a digest, a clock reading), sans for\n     anything read as language. Named families first, because a generic\n     fallback resolving to something else is a fact worth catching rather\n     than assuming away -- Cascadia Mono and Segoe UI Variable Text are both\n     present on the platform this app ships to first; the remaining names\n     are real fallbacks, not decoration. */\n  --mono: \"Cascadia Mono\", ui-monospace, \"SF Mono\", SFMono-Regular, Menlo, Consolas,\n          \"DejaVu Sans Mono\", \"Liberation Mono\", \"Noto Sans Mono\", monospace;\n  --sans: \"Segoe UI Variable Text\", \"Segoe UI\", ui-sans-serif, -apple-system, \"SF Pro Text\",\n          \"Noto Sans\", \"DejaVu Sans\", sans-serif;\n\n  /* One scale, every step at or above SS558's 14px body floor (\"small text\n     is a defect\", stated as a hard requirement, not a preference) -- the\n     retired file's --t-time (13px) and --t-meta (12px) both sat under that\n     floor; this derivation raises both to the floor rather than reproducing\n     a number the current canon calls a defect. Differentiation between\n     meta/time/record now comes from colour, family and line-height, not\n     from three different sizes squeezed under 14px. */\n  --t-meta: 14px;   --lh-meta: 18px;\n  --t-time: 14px;   --lh-time: 19px;\n  --t-record: 14px; --lh-record: 20px;\n  --t-head: 17px;   --lh-head: 24px;\n\n  /* Owner #388 (req/822_c7 §3): the 単調 root cause was a scale with exactly two sizes,\n     14 and 17 -- a stat number drew at the same optical weight as its own caption, so\n     nothing on the page led the eye. Two steps join the scale, both OUTSIDE the body\n     band, so the SS558 floor is untouched:\n     --t-stat is for a counted fact standing alone in a stat cell (mono, so 6 and 0\n     hold their width while the count moves); --t-label is for an UPPERCASE small-caps\n     label riding above or under such a number -- never for sentence text, which keeps\n     the 14px floor exactly as SS558 states it: small READING text is a defect; a\n     tracked-out uppercase caption is a different organ. */\n  --t-stat: 26px;   --lh-stat: 30px;\n  /* --t-label is DECLARED AND DORMANT: parts/test/surface.test.mjs pins on-screen\n     labels to the record size (req/38 SS693 -- the 14px floor is hard, and the figure\n     above a label is what carries the hierarchy). The token stands only for a future\n     surface that is not read at arm's length (print, export); nothing on screen may\n     consume it while SS693 stands. */\n  --t-label: 12.5px; --lh-label: 16px; --track-label: 0.08em;\n\n  /* One spacing rhythm (req/822_c7 §3) -- gaps were picked per call site; four names,\n     chosen by what the gap separates: inside a chip, between siblings, between organs,\n     between sections. */\n  --space-1: 4px; --space-2: 8px; --space-3: 16px; --space-4: 24px;\n\n  /* ================================================================================\n     req/884 (Owner #423/#424, seat=Opus, 2026-08-26, 暫定 -- 再審査可)\n     ONE TOKEN SET FOR EVERY INTERACTION.\n\n     Everything from here down was, until this document, either a literal at a call\n     site or a private roster in another file. Both are the same defect wearing two\n     hats: a value nobody can retune from the roster. The families below are named so\n     the machine check (tools/protocol_gate.mjs) can say, of any literal it finds,\n     \"there is a token for this\" -- which is the only form of this rule that holds.\n\n     Derivation is stated per family. Where a value is unchanged from what the tree\n     already drew, it is PROMOTED, not invented, and the promotion is said so that\n     nobody re-derives it later (feedback_dont_rederive_settled_env_facts).\n     ================================================================================ */\n\n  /* ---- ground steps ---------------------------------------------------------------\n     PROMOTED from shell/kernel/shell.css:26-30, where they were declared on `.shell`.\n     That file's own header says \"Not one colour is written here\", and it was telling\n     the truth about hex literals -- but a color-mix() of two tokens under a NEW name\n     is a new value, and the name was reachable only from the frame. The faces could\n     not spell it, which is exactly why shell chrome and face interiors disagreed about\n     what a hover looks like. Same mixtures, same numbers; one roster now owns them. */\n  --surface-0: var(--bg);\n  --surface-1: color-mix(in srgb, var(--ink) 4%, var(--bg));  /* hover bed */\n  --surface-2: color-mix(in srgb, var(--ink) 8%, var(--bg));  /* pressed / open bed */\n  --crease: var(--line);\n  --tension: color-mix(in srgb, var(--ink) 22%, var(--bg));   /* the edge under a pointer */\n\n  /* ---- interaction states ---------------------------------------------------------\n     Owner #423: pointer, left click, right click, drag, hover, focus, keyboard and the\n     effect each produces are ONE layer. The census (req/884 §2) found the effect half\n     scattered across nine literal sites and the pointer half across fifteen.\n\n     `--press-y` is the whole of what a press looks like: 1px, a compositor transform,\n     nothing around it moves. It was already 1px in two independent places\n     (shell.css:109 and parts/src/surface.mjs:145) which agreed by luck, not by rule. */\n  --press-y: 1px;\n\n  /* The focus ring. Width and offset were literal at three sites; the colour was\n     already tokenised, which is how a half-tokenised value hides. `--focus-offset-in`\n     is the act-gutter's tighter variant (parts/src/surface.mjs:161) -- a real second\n     case, so it gets a real second name rather than being rounded into the first. */\n  --focus-w: 2px;\n  --focus-offset: -2px;\n  --focus-offset-in: 1px;\n  --focus-ink: var(--act);\n\n  /* Two opacities, and the tree had four. 0.4 (shell.css:789 button[disabled]), 0.6\n     (shell.css:719 .strip-step:disabled), 0.55 and 1 (shell.css:650-651, tab-close and\n     pane-tool idle vs revealed). 0.6 and 0.4 were two spellings of \"this control will\n     not answer\", so they collapse to one: a reader cannot be expected to read 0.4 as\n     more-disabled than 0.6. 0.55 is a DIFFERENT fact -- the control will answer, it is\n     simply not being asked for yet -- so it keeps its own name. */\n  --disabled-opacity: 0.4;\n  --idle-opacity: 0.55;\n\n  /* Pointers. Every cursor in the tree was a literal, which is defensible only until\n     you want to know how many kinds of pointer this application has. It has six, and\n     they are named by what the pointer PROMISES, not by the CSS keyword, so a call\n     site that writes `var(--cursor-refuse)` cannot quietly mean \"default\". */\n  --cursor-act: pointer;        /* this will answer a press */\n  --cursor-refuse: not-allowed; /* this exists and will not answer -- and says why */\n  --cursor-inert: default;      /* not a control (a solo tab is its pane's title) */\n  --cursor-text: text;          /* a field */\n  --cursor-size-x: col-resize;  /* a vertical sash moves along x */\n  --cursor-size-y: row-resize;  /* a horizontal sash moves along y */\n\n  /* Drag and drop. The sash was the only draggable thing in the window and it carried\n     its own timing (shell.css:579, `90ms ease-out` -- the ONE motion literal that\n     bypassed --motion-quick/--motion-ease entirely) and its own idle thickness\n     (scaleX(0.34)). Both are named here; the timing now joins the shared route. */\n  --drag-bar-scale: 0.34;   /* the sash's resting thickness, as a fraction of its hit area */\n  --drag-ghost-opacity: 0.6;\n  --drop-bed: var(--act-bed);\n  --drop-edge: var(--act);\n\n  /* ---- scrollbar (Owner #423追記1) -------------------------------------------------\n     The Owner finds the web scrollbar hard to see. It is hard to see for two reasons\n     and this file fixes both.\n\n     (1) It was declared TWICE -- shell/kernel/shell.css:68-75 and parts/src/surface.mjs\n     -- with the numbers written out at both sites (8px, radius 4px). Two declarations\n     of one thing is how a surface ends up with a scrollbar that does not match the\n     surface beside it.\n     (2) The thumb was --crease, which is the SAME token as the rule between sections.\n     A thumb the colour of a hairline is a thumb you cannot find. 凌駕, not 踏襲: the\n     thumb takes --tension (ink at 22%, the token that already means \"an edge under a\n     pointer\"), which is roughly five times the contrast against the page that --crease\n     carries, and the track goes transparent so the thumb is the only thing drawn.\n     Width goes 8px -> 10px: still slim, but above the 8px at which a thumb on a\n     high-DPI panel reads as a hairline.\n\n     Named for adoption, not just for us: req/885's landing pages were told to consume\n     these rather than invent a local fix, so the names say `scrollbar`, not `sash` or\n     `rail` or any noun private to this window. */\n     MEASURED, not asserted (req/884 §2-4a, and this is the second draft). The first draft\n     of this block gave the thumb `--tension` (ink at 22%), which measures 1.58:1 light /\n     1.83:1 dark against the page -- better than the 1.12:1 / 1.32:1 the hairline gave, and\n     STILL UNDER the 3:1 WCAG non-text floor. req/885 independently measured the old thumb\n     at 1.23:1 / 1.15:1 and reached the same diagnosis from the other end, which is the\n     only reason to believe either reading. \"Better\" is not a floor, so the thumb takes its\n     own step at ink 50%: 3.20:1 on the light page, 4.56:1 on the dark one. One percentage\n     clears both, so there is one value and not a per-theme pair. */\n  --scrollbar-w: 10px;\n  --scrollbar-track: transparent;\n  --scrollbar-thumb: color-mix(in srgb, var(--ink) 50%, var(--bg));       /* 3.20:1 light, 4.56:1 dark */\n  --scrollbar-thumb-hover: color-mix(in srgb, var(--ink) 65%, var(--bg)); /* 5.09:1 light, 7.0:1 dark */\n  --scrollbar-radius: var(--radius-1);\n\n  /* ---- glyph sizing ---------------------------------------------------------------\n     Owner #424. A glyph arrived at whatever size its container implied, which is how\n     req/04a's unsized-glyph defect happened (a second builder assembled its own <svg>\n     and the sizing rule had been written for the first builder's container). Two\n     sizes, chosen by the same rule the radius tiers use -- what the thing IS: a mark\n     inside a line of text, or a mark a hand lands on. Stroke is stated once so a glyph\n     drawn at either size has the same optical weight. */\n     Stroke and opacity are PROMOTED from shell.css:784 (`.mark`), not chosen here. The\n     first draft of this block declared 1.5 because that is a common glyph weight, and\n     the tree draws 1.25 -- inventing a value where the roster's whole job is to hold the\n     one already in use would have silently re-weighted every mark in the window on the\n     commit that claimed to change nothing. Caught by reading the call site the gate\n     pointed at, which is the argument for having the gate point at call sites. */\n  --glyph-1: 14px;      /* inside a line -- beside a word, in a chip */\n  --glyph-2: 16px;      /* a control a hand lands on */\n  --glyph-stroke: 1.25;\n  --glyph-opacity: 0.8; /* a mark reads a step lighter than the text it stands beside */\n\n  /* ---- elevation ------------------------------------------------------------------\n     The two floating surfaces carried literal shadows (shell.css:812 palette,\n     shell.css:882 chrome menu). Two names, because there genuinely are two heights:\n     a menu sits just off the thing it belongs to, a palette sits over the whole window.\n     Stated as complete shadows rather than as offsets a call site reassembles. */\n  --shadow-menu: 0 12px 32px color-mix(in srgb, var(--ink) 18%, transparent);\n  --shadow-palette: 0 18px 48px color-mix(in srgb, var(--ink) 24%, transparent);\n\n  /* ---- the accent that fires once (req/851 hue budget, resolved by #425) -----------\n     req/851 extracted a constitution rule this tree has never applied: ONE accent,\n     bound to ONE meaning, firing exactly once per screen. Taken flat, that rule\n     contradicts Owner #340, which is recorded 60 lines above this one and deliberately\n     spent FIVE hues so a stranger could tell an admitted row from a denied one. Both\n     rulings are live and neither is being overruled here, so the contradiction has to\n     be dissolved rather than voted on.\n\n     It dissolves because the two rules govern different axes. #340's five hues are a\n     CLASSIFICATION -- they say what standing a row is in, and a table of forty rows is\n     supposed to be legible as forty standings. req/851's single accent is an ALARM --\n     it is not classifying anything, it fires at most once, and #425 names the moment it\n     fires for: \"this change cannot be undone, proceed?\" (invert.rs E-M3-4, statutory in\n     spec 44 section 338). #425 calls that the single most prominent moment in the whole\n     UI, and it is the product.\n\n     So the alarm gets a ROLE, not a sixth hue. Spending a new hue on a palette the\n     Owner has already called both monotone (#340) and repainted (#424) would be the\n     wrong answer twice over. The alarm IS the deny ink, reserved -- and what makes it\n     an alarm rather than another red chip is that it is the one place the ink is spent\n     filled, at full bed, and that tools/protocol_gate.mjs counts its sites and holds\n     the count at one per screen. A budget nobody counts is a preference. */\n  --alarm: var(--deny);\n  --alarm-bed: var(--deny-bed);\n  --alarm-edge: var(--deny);\n}\n\n:root {\n  /* light palette, declared under the --l- prefix parts/src/tokens.mjs's\n     palettes() reads as the light bucket. Measured against its own --l-bg,\n     not derived from the dark side by a formula -- a page is read on its\n     own page, not translated from the other one. */\n  --l-bg: #f6f5f2;\n  --l-bg-raised: #fffdf9;  /* --l-ink on it: 16.59:1 -- the paper's card, one step brighter */\n  --l-bg-inset: #efede8;   /* --l-ink on it: 14.41:1, --l-ink-2 on it: 6.47:1 */\n  --l-ink: #1d1d1d;    /* measured 15.46:1 against --l-bg */\n  --l-ink-2: #545454;  /* measured 6.95:1 */\n  --l-ink-3: #717171;  /* measured 4.48:1 -- within half a step of the 4.5:1 normal-text floor,\n                           and weaker here than on the dark side: too close to the line to set\n                           text in on this app's own default page, which is exactly why\n                           parts/src/tokens.mjs forbids it rather than leaving the judgement to\n                           whoever reaches for a third ink next. */\n  --l-line: #e8e8e8;\n  --l-deny: #c8321e;   /* measured 4.90:1 */\n\n  /* The standing hues again, derived against the light page rather than translated\n     from the dark one -- the same discipline the inks above already follow, and the\n     reason it matters here is that a hue bright enough to read on #0a0a0c is close to\n     unreadable on #f6f5f2. Each figure is its own measurement. */\n  --l-act: #1d5f8a;        /* 6.30:1 against --l-bg */\n  --l-act-bed: #e2eef6;    /* --l-act on it: 5.82:1 */\n  --l-admit: #176b3d;      /* 6.01:1 */\n  --l-admit-bed: #e3f2e8;  /* --l-admit on it: 5.65:1 */\n  --l-deny-bed: #fdf0ee;   /* --l-deny on it: 4.80:1 */\n  --l-escalate: #8a5a06;   /* 5.43:1 */\n  --l-escalate-bed: #fbeed4; /* --l-escalate on it: 5.16:1 */\n  --l-held: #3f4fae;       /* 6.55:1 */\n  --l-held-bed: #e7eaf9;   /* --l-held on it: 5.96:1 */\n}\n\n/* Explicit theme choice wins over anything else. */\n:root[data-theme=\"light\"] {\n  --bg: var(--l-bg); --bg-raised: var(--l-bg-raised); --bg-inset: var(--l-bg-inset);\n  --ink: var(--l-ink); --ink-2: var(--l-ink-2); --ink-3: var(--l-ink-3);\n  --line: var(--l-line); --deny: var(--l-deny);\n  --act: var(--l-act); --act-bed: var(--l-act-bed);\n  --admit: var(--l-admit); --admit-bed: var(--l-admit-bed);\n  --deny-bed: var(--l-deny-bed);\n  --escalate: var(--l-escalate); --escalate-bed: var(--l-escalate-bed);\n  --held: var(--l-held); --held-bed: var(--l-held-bed);\n}\n\n/* SS551/SS558: this app's stated default is light (a standing rejection of\n   the generic-dark-devtool look), not \"whichever the OS prefers\" -- but\n   nailing data-theme=\"light\" onto the document itself, so no reader's OS\n   preference can ever move it, is an open item this stylesheet alone cannot\n   settle (parts/README.md already files it: light-default and \"do not nail\n   the theme to the page\" do not both hold under a bare :root that is dark by\n   parser contract, and settling it needs a shell-level ruling, req/02). What\n   this rule can honestly do is answer an explicit light preference without\n   requiring data-theme to be set by hand. Dark stays the parser-contract\n   default (bare :root, above) until that shell-level ruling lands. */\n@media (prefers-color-scheme: light) {\n  :root:not([data-theme=\"dark\"]) {\n    --bg: var(--l-bg); --bg-raised: var(--l-bg-raised); --bg-inset: var(--l-bg-inset);\n    --ink: var(--l-ink); --ink-2: var(--l-ink-2); --ink-3: var(--l-ink-3);\n    --line: var(--l-line); --deny: var(--l-deny);\n    --act: var(--l-act); --act-bed: var(--l-act-bed);\n    --admit: var(--l-admit); --admit-bed: var(--l-admit-bed);\n    --deny-bed: var(--l-deny-bed);\n    --escalate: var(--l-escalate); --escalate-bed: var(--l-escalate-bed);\n    --held: var(--l-held); --held-bed: var(--l-held-bed);\n  }\n}\n\n@media (max-width: 1000px) {\n  :root { --detail-x: 0px; }\n}\n";
